const d = n => new Date(Date.now() - n*86400000).toISOString().slice(0,10);
const daysSince = s => Math.floor((Date.now() - new Date(s).getTime())/86400000);
const {open_slots, clients} = $input.first().json;
const used = new Set();
return open_slots.map(slot => {
 const pool = clients
  .filter(c => c.marketing_ok && c.treatment === slot.treatment && !used.has(c.id))
  .sort((a, b) => (b.waitlist - a.waitlist) || (daysSince(b.last_visit) - daysSince(a.last_visit)));
 const c = pool[0];
 if (c) used.add(c.id);
 return {json: {...slot, client: c || null, needs_action: !!c, reason: c ? (c.waitlist ? 'waitlist match' : `lapsed ${daysSince(c.last_visit)} days`) : 'no consenting client for this treatment'}};
});

return $input.all().map(({json}) => {
 const c = json.client;
 const first = c.name.split(' ')[0];
 const message = `Hi ${first}, a ${json.treatment} appointment has opened at Lumen on ${json.date} at ${json.time}. Reply YES to take it and we will confirm. This message was prepared by an automated assistant. Reply STOP to opt out.`;
 return {json: {...json, id: json.slot_id, channel:'email', to: c.email, subject:`A ${json.treatment} slot just opened`, message, approval:'auto_send'}};
});
